import { Component, Method, Prop, setAssetPath } from "@stencil/core";
import { version } from "../../../package.json";

@Component({
	tag: "hbr-context",
})
export class Context {
	pack = Number(version.slice(version.lastIndexOf(".") + 1)) || 0;

	/** the harbor version */
	@Prop({ mutable: true }) version: string;

	/** Method to manually set the asset base path where assets can be found */
	@Method()
	async setAssetPath(path) {
		setAssetPath(path);
		return Promise.resolve();
	}

	componentWillLoad() {
		if (typeof window === "undefined") {
			return;
		}
		const harborSide =
			window.location.hostname.includes("localhost") ||
			window.location.hostname.includes("harbor");
		if (!harborSide) {
			this.pack++;
		}

		this.version = `v.${version.replace(
			/\.[^.]*$/,
			`.${this.pack.toString()}`,
		)}`;
	}
	render() {
		return this.version;
	}
}
